(function(){if(window.__siteLayoutToggleInitialized){return;}
window.__siteLayoutToggleInitialized=true;var STORAGE_KEY='kl-site-layout';var LAYOUTS=['embedded','floating','flat'];var DEFAULT_LAYOUT='embedded';var detachedPanel=null;var detachedPanelHome=null;function normalizeLayout(layout){return LAYOUTS.indexOf(layout)!==-1?layout:DEFAULT_LAYOUT;}
function readLayout(){try{return normalizeLayout(localStorage.getItem(STORAGE_KEY));}catch(error){return DEFAULT_LAYOUT;}}
function writeLayout(layout){try{localStorage.setItem(STORAGE_KEY,normalizeLayout(layout));}catch(error){console.warn('[layout-toggle] 无法写入本地布局状态',error);}}
function closeDropdown(){restoreDropdown();document.querySelectorAll('.site-layout-toggle--open').forEach(function(wrapper){wrapper.classList.remove('site-layout-toggle--open');});document.querySelectorAll('[data-layout-toggle]').forEach(function(button){button.setAttribute('aria-expanded','false');});}
function openDropdown(wrapper,panel){var portal=document.querySelector('.site-header-portal');if(!portal||typeof window.positionHeaderDropdown!=='function'){return false;}
if(panel.parentElement!==portal){detachedPanel=panel;detachedPanelHome=wrapper;portal.appendChild(panel);}
panel.dataset.dropdownFor=wrapper.id;window.positionHeaderDropdown(wrapper,panel);if(window.siteLiquidGlass){window.siteLiquidGlass.apply(panel);}
panel.classList.add('is-open');return true;}
function restoreDropdown(){if(!detachedPanel){return;}
detachedPanel.classList.remove('is-open');if(detachedPanelHome&&detachedPanelHome.isConnected){detachedPanelHome.appendChild(detachedPanel);}
detachedPanel=null;detachedPanelHome=null;}
function syncOptions(layout){document.querySelectorAll('[data-layout-option]').forEach(function(option){var selected=option.getAttribute('data-layout-option')===layout;option.setAttribute('aria-pressed',selected?'true':'false');});}
function applyLayout(layout){var normalized=normalizeLayout(layout);var root=document.documentElement;if(root.getAttribute('data-site-layout')!==normalized){document.dispatchEvent(new Event('site-layout-before-change'));}
root.setAttribute('data-site-layout',normalized);writeLayout(normalized);syncOptions(normalized);}
function getForcedLayout(){var marker=document.querySelector('[data-site-force-layout]');return marker?marker.getAttribute('data-site-force-layout'):null;}
function enforcePageLayout(){var forced=getForcedLayout();var root=document.documentElement;if(forced&&LAYOUTS.indexOf(forced)!==-1){root.setAttribute('data-site-layout',forced);}else{root.setAttribute('data-site-layout',readLayout());}
syncOptions(readLayout());}
function updateToggleVisibility(){var toggle=document.querySelector('.site-layout-toggle');if(!toggle){return;}
toggle.style.display=getForcedLayout()?'none':'';}
function subscribeToPageChanges(callback){if(typeof document$!=='undefined'&&typeof document$.subscribe==='function'){document$.subscribe(function(){window.requestAnimationFrame(callback);});return;}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',callback,{once:true});return;}
callback();}
document.addEventListener('click',function(event){var toggleButton=event.target.closest('[data-layout-toggle]');if(toggleButton){var wrapper=toggleButton.closest('.site-layout-toggle');if(wrapper){var willOpen=!wrapper.classList.contains('site-layout-toggle--open');if(willOpen&&typeof window.closeAllHeaderDropdownsExcept==='function'){window.closeAllHeaderDropdownsExcept(wrapper);}else{closeDropdown();}
var panel=wrapper.querySelector('.site-layout-dropdown')||detachedPanel;if(willOpen&&(!panel||!openDropdown(wrapper,panel))){return;}
wrapper.classList.toggle('site-layout-toggle--open',willOpen);toggleButton.setAttribute('aria-expanded',willOpen?'true':'false');}
return;}
var option=event.target.closest('[data-layout-option]');if(option){applyLayout(option.getAttribute('data-layout-option'));closeDropdown();return;}
if(!event.target.closest('.site-layout-dropdown')){closeDropdown();}});document.addEventListener('keydown',function(event){if(event.key==='Escape'){closeDropdown();}});function initialize(){closeDropdown();enforcePageLayout();updateToggleVisibility();}
subscribeToPageChanges(initialize);})();